/// <summary>
/// Application Insights property for the number of errors in a message.
/// </summary>
public class OMGApplicationInsightsMessageErrorCountProperty extends SysApplicationInsightsProperty
{
}

Method.Source:
/// <summary>
/// Initializes a new instance of the <see cref="OMGApplicationInsightsMessageErrorCountProperty"/> class.
/// </summary>
/// <param name="_errorCount">The number of errors in a message.</param>
/// <returns>The new instance.</returns>
public static OMGApplicationInsightsMessageErrorCountProperty newFromErrorCount(int64 _errorCount)
{
    return new OMGApplicationInsightsMessageErrorCountProperty(int642Str(_errorCount));
}
